                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.AV_MASTER_HTMBASE AS WITH product_images AS ( SELECT sku_group, image_url FROM snitch_db.maplemonk.base_product ), metafields_std AS ( SELECT sku_group, product_name, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' ELSE \'Others\' END WHEN UPPER(category) LIKE \'%SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Printed\' ELSE \'Other\' END ELSE designs END AS designs_new, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN TRIM(LOWER(collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(collar_new)) = \'polo\' THEN \'Polo\' ELSE \'Others\' END ELSE collar_new END AS collar_new_modified, fit, CASE WHEN UPPER(STYLE) LIKE \'%LUXE%\' OR UPPER(sku_group) LIKE \'4MLX%\' OR UPPER(sku_group) LIKE \'4LRN%\' OR UPPER(sku_group) LIKE \'4LPL%\' OR UPPER(sku_group) LIKE \'4LTR%\' OR UPPER(sku_group) LIKE \'4LCH%\' OR UPPER(sku_group) LIKE \'4LJE%\' OR UPPER(sku_group) LIKE \'4LJK%\' OR UPPER(sku_group) LIKE \'4LSW%\' OR UPPER(sku_group) LIKE \'4LHD%\' OR UPPER(sku_group) LIKE \'4LOS%\' OR UPPER(sku_group) LIKE \'4LSHS%\' OR UPPER(sku_group) LIKE \'4LSFS%\' OR UPPER(sku_group) LIKE \'4LSH%\' OR UPPER(sku_group) LIKE \'4LBL%\' OR UPPER(sku_group) LIKE \'4LCA%\' OR UPPER(sku_group) LIKE \'4LSWT%\' OR UPPER(sku_group) LIKE \'4LCD%\' OR UPPER(sku_group) LIKE \'4LJO%\' THEN \'Luxe\' WHEN UPPER(STYLE) LIKE \'%PLUS%\' OR UPPER(sku_group) like \'%4BJ002%\' OR UPPER(sku_group) LIKE \'4MBG%\' OR UPPER(sku_group) LIKE \'4BRN%\' OR UPPER(sku_group) LIKE \'4BPL%\' OR UPPER(sku_group) LIKE \'4BTR%\' OR UPPER(sku_group) LIKE \'4BCH%\' OR UPPER(sku_group) LIKE \'4BJE%\' OR UPPER(sku_group) LIKE \'4BJK%\' OR UPPER(sku_group) LIKE \'4BSW%\' OR UPPER(sku_group) LIKE \'4BHD%\' OR UPPER(sku_group) LIKE \'4BOS%\' OR UPPER(sku_group) LIKE \'4BSHS%\' OR UPPER(sku_group) LIKE \'4BSFS%\' OR UPPER(sku_group) LIKE \'4BSH%\' OR UPPER(sku_group) LIKE \'4BBL%\' OR UPPER(sku_group) LIKE \'4BCA%\' OR UPPER(sku_group) LIKE \'4BSWT%\' OR UPPER(sku_group) LIKE \'4BCD%\' OR UPPER(sku_group) LIKE \'4BJO%\' THEN \'Plus\' when upper(sku_group) like \'MP%\' THEN \'MP\' ELSE \'Snitch\' END AS style, CASE WHEN TRIM(LOWER(sleeve_type)) IN (\'sleeveless\') THEN \'Sleeveless\' WHEN TRIM(LOWER(sleeve_type)) IN (\'half sleeve\',\'elbow sleeve\') THEN \'Half Sleeve\' WHEN TRIM(LOWER(sleeve_type)) IN (\'full sleeve\',\'three-quarter sleeves\') THEN \'Full Sleeve\' ELSE \'Others\' END AS sleeve_length, CASE WHEN LOWER(STYLE) LIKE \'%linen%\' THEN \'Linen\' WHEN MATERIAL_NEW = \'Cotton\' THEN \'Cotton\' WHEN MATERIAL_NEW IN (\'Tencel\', \'Tencil\', \'Polyester\', \'Terry\', \'Rayon\', \'Nylon\', \'Modal\', \'Others\') THEN \'Polyester\' WHEN MATERIAL_NEW = \'Linen\' THEN \'Linen\' ELSE \'Polyester\' END AS material FROM SNITCH_DB.MAPLEMONK.metafields_data ), offline_inv AS ( SELECT s.zone, UPPER(o.sku_group) AS sku_group, SUM(o.inventory) + SUM(o.jit_qty) AS offline_inventory, COUNT(DISTINCT CASE WHEN (o.inventory + o.jit_qty) > 0 THEN o.branch_code END) AS region_store_count FROM snitch_db.maplemonk.offline_master o JOIN ( SELECT DISTINCT branch_code, zone FROM snitch_db.maplemonk.store_category_delta ) s ON o.branch_code = s.branch_code GROUP BY 1, 2 ) SELECT a.warehouse_location, a.sku_group, COALESCE(a.product_name, m.product_name) AS product_name, a.category, a.sellable_inventory, COALESCE(off.offline_inventory, 0) AS offline_inventory, COALESCE(off.region_store_count, 0) AS region_store_count, m.designs_new AS designs, m.collar_new_modified AS collar_new, m.fit, CASE WHEN UPPER(CATEGORY) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\') THEN \'Long_Tail\' WHEN UPPER(a.sku_group) LIKE \'4MLX%\' OR UPPER(a.sku_group) LIKE \'4LRN%\' OR UPPER(a.sku_group) LIKE \'4LPL%\' OR UPPER(a.sku_group) LIKE \'4LTR%\' OR UPPER(a.sku_group) LIKE \'4LCH%\' OR UPPER(a.sku_group) LIKE \'4LJE%\' OR UPPER(a.sku_group) LIKE \'4LJK%\' OR UPPER(a.sku_group) LIKE \'4LSW%\' OR UPPER(a.sku_group) LIKE \'4LHD%\' OR UPPER(a.sku_group) LIKE \'4LOS%\' OR UPPER(a.sku_group) LIKE \'4LSHS%\' OR UPPER(a.sku_group) LIKE \'4LSFS%\' OR UPPER(a.sku_group) LIKE \'4LSH%\' OR UPPER(a.sku_group) LIKE \'4LBL%\' OR UPPER(a.sku_group) LIKE \'4LCA%\' OR UPPER(a.sku_group) LIKE \'4LSWT%\' OR UPPER(a.sku_group) LIKE \'4LCD%\' OR UPPER(a.sku_group) LIKE \'4LJO%\' THEN \'Luxe\' WHEN UPPER(a.sku_group) LIKE \'4MBG%\' OR UPPER(a.sku_group) like \'%4BJ002%\' OR UPPER(a.sku_group) LIKE \'4BRN%\' OR UPPER(a.sku_group) LIKE \'4BPL%\' OR UPPER(a.sku_group) LIKE \'4BTR%\' OR UPPER(a.sku_group) LIKE \'4BCH%\' OR UPPER(a.sku_group) LIKE \'4BJE%\' OR UPPER(a.sku_group) LIKE \'4BJK%\' OR UPPER(a.sku_group) LIKE \'4BSW%\' OR UPPER(a.sku_group) LIKE \'4BHD%\' OR UPPER(a.sku_group) LIKE \'4BOS%\' OR UPPER(a.sku_group) LIKE \'4BSHS%\' OR UPPER(a.sku_group) LIKE \'4BSFS%\' OR UPPER(a.sku_group) LIKE \'4BSH%\' OR UPPER(a.sku_group) LIKE \'4BBL%\' OR UPPER(a.sku_group) LIKE \'4BCA%\' OR UPPER(a.sku_group) LIKE \'4BSWT%\' OR UPPER(a.sku_group) LIKE \'4BCD%\' OR UPPER(a.sku_group) LIKE \'4BJO%\' THEN \'Plus\' WHEN UPPER(a.sku_group) LIKE \'MP%\' THEN \'MP\' ELSE \'Snitch\' END AS style, m.material, CASE WHEN UPPER(a.sku_group) IN ( SELECT DISTINCT UPPER(\"SKU Group\") FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE category IN (\'Collection\')) THEN \'Collection\' WHEN UPPER(a.sku_group) IN ( SELECT DISTINCT UPPER(\"SKU Group\") FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE category IN (\'BDay_Sale\')) THEN \'BDay_Sale\' WHEN UPPER(a.sku_group) IN ( SELECT DISTINCT UPPER(\"SKU Group\") FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE category NOT IN (\'Collection\',\'Online NOOS\',\'BDay_Sale\') ) THEN \'EOSS\' ELSE \'Fresh\' END AS allocation_status, m.sleeve_length, a.live_date, pi.image_url AS image_link, CASE WHEN UPPER(A.SKU_GROUP) LIKE \'4MSFR%\' THEN ROUND(((A.SELLABLE_INVENTORY-2)/12),0) WHEN UPPER(A.SKU_GROUP) LIKE \'SN%\' THEN ROUND(((A.SELLABLE_INVENTORY-1)/4),0) WHEN UPPER(A.SKU_GROUP) LIKE \'BP%\' THEN ROUND(((A.SELLABLE_INVENTORY-1)/3),0) WHEN UPPER(A.SKU_GROUP) LIKE \'4MCP%\' THEN ROUND(((A.SELLABLE_INVENTORY-1)/3),0) WHEN UPPER(A.SKU_GROUP) LIKE \'SH0%\' THEN GREATEST(LEAST( ROUND((a.S_UNITS - 1) / 2), ROUND((a.M_UNITS - 1) / 2), ROUND((a.L_UNITS - 1) / 2), ROUND((a.XL_UNITS - 1) / 2) ), 0) WHEN UPPER(A.SKU_GROUP) LIKE \'4MBL%\' THEN GREATEST(LEAST( ROUND((a.M_UNITS - 1) / 2), ROUND((a.XL_UNITS - 1) / 2), ROUND((a.XL3_UNITS - 1) / 2) ), 0) WHEN UPPER(a.sku_group) LIKE \'4MBG%\' OR UPPER(a.sku_group) like \'%4BJ002%\' OR UPPER(a.sku_group) LIKE \'4BRN%\' OR UPPER(a.sku_group) LIKE \'4BPL%\' OR UPPER(a.sku_group) LIKE \'4BTR%\' OR UPPER(a.sku_group) LIKE \'4BCH%\' OR UPPER(a.sku_group) LIKE \'4BJE%\' OR UPPER(a.sku_group) LIKE \'4BJK%\' OR UPPER(a.sku_group) LIKE \'4BSW%\' OR UPPER(a.sku_group) LIKE \'4BHD%\' OR UPPER(a.sku_group) LIKE \'4BOS%\' OR UPPER(a.sku_group) LIKE \'4BSHS%\' OR UPPER(a.sku_group) LIKE \'4BSFS%\' OR UPPER(a.sku_group) LIKE \'4BSH%\' OR UPPER(a.sku_group) LIKE \'4BBL%\' OR UPPER(a.sku_group) LIKE \'4BCA%\' OR UPPER(a.sku_group) LIKE \'4BSWT%\' OR UPPER(a.sku_group) LIKE \'4BCD%\' OR UPPER(a.sku_group) LIKE \'4BJO%\' THEN GREATEST(LEAST( ROUND((a.XL3_UNITS - 1) / 3), ROUND((a.XL4_UNITS - 1) / 3), ROUND((a.XL5_UNITS - 1) / 2), ROUND((a.XL6_UNITS - 1) / 2) ), 0) WHEN UPPER(a.category) LIKE \'%JEANS%\' AND COALESCE(m.style, \'Snitch\') <> \'Plus\' THEN CASE WHEN GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) > 0 THEN GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) ELSE GREATEST( LEAST( ROUND((a.xs_units - 1) / 2), ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4) ), LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), LEAST( ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3), ROUND((a.xxl_units - 1) / 2) ), 0 ) END ELSE GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) END AS full_size_options, a.xs_units, a.s_units, a.m_units, a.l_units, a.xl_units, a.xxl_units, a.xl3_units, a.xl4_units, a.xl5_units, a.xl6_units, a.xl7_units, a.xl8_units FROM SNITCH_DB.MAPLEMONK.availability_master_v2_merged a LEFT JOIN metafields_std m ON a.sku_group = m.sku_group LEFT JOIN product_images pi ON a.sku_group = pi.sku_group LEFT JOIN offline_inv off ON UPPER(a.warehouse_location) = UPPER(off.zone) AND UPPER(a.sku_group) = off.sku_group WHERE a.sellable_inventory > 0 AND a.sku_group NOT LIKE \'%_T\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.off_master_htmlbase AS WITH opening AS ( SELECT date AS opening_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS opening_inventory, new_category, designs, collar_new, sleeve_type, fit, style, material_new FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date = current_date - 30 ), closing AS ( SELECT current_date AS closing_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, jit_qty, num_size_available, new_category, designs, XS_UNITS,S_UNITS,M_UNITS,L_UNITS,XL_UNITS,XXL_UNITS,XL3_UNITS,XL4_UNITS,XL5_UNITS,XL6_UNITS,JIT_XS_UNITS,JIT_S_UNITS,JIT_M_UNITS,JIT_L_UNITS,JIT_XL_UNITS,JIT_2XL_UNITS,JIT_3XL_UNITS,JIT_4XL_UNITS,JIT_5XL_UNITS,JIT_6XL_UNITS, CASE WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( (CASE WHEN XL3_UNITS + JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS + JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS + JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS + JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 THEN \'YES\' ELSE \'NO\' END ELSE CASE WHEN ( (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 3 OR ( (CASE WHEN XS_UNITS + JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS + JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS + JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS + JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS + JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS + JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END END AS cut_size, collar_new, sleeve_type, fit, style, material_new, sales_last_7_days, CASE WHEN fresh_inventory > 0 AND fresh_inventory = inventory THEN \'Fresh\' ELSE \'Old\' END AS fresh_remark FROM snitch_db.maplemonk.offline_master ), sales AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS sales_qty FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN current_date - 30 AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix NOT IN (\'QCOM\',\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), sales_mtd AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS sales_qty_mtd FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN date_trunc(\'month\', current_date) AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix NOT IN (\'QCOM\',\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), omni_sales_30 AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS omni_sales_qty FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN current_date - 30 AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix IN (\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), omni_sales_mtd AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS omni_sales_qty_mtd FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN date_trunc(\'month\', current_date) AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\' ) AND doc_prefix IN (\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), base_stock AS ( SELECT branch_code, MAX(base_stock) AS base_stock FROM snitch_db.maplemonk.offline_master WHERE branch_code IS NOT NULL AND base_stock IS NOT NULL GROUP BY branch_code ), combined AS ( SELECT COALESCE(o.branch_code, c.branch_code, s.branch_code) AS branch_code, c.cluster AS cluster, COALESCE(c.marketplace_mapped, s.marketplace_mapped) AS marketplace_mapped, COALESCE(o.sku_group, c.sku_group, s.sku_group) AS sku_group, COALESCE(o.opening_inventory, 0) AS opening_inventory, COALESCE(c.closing_inventory, 0) AS closing_inventory, COALESCE(c.jit_qty, 0) AS jit_qty, COALESCE(c.num_size_available, 0) AS num_size_available, COALESCE(s.sales_qty, 0) AS sales_qty, COALESCE(smtd.sales_qty_mtd, 0) AS sales_qty_mtd, COALESCE(os30.omni_sales_qty, 0) AS omni_sales_qty, COALESCE(osmtd.omni_sales_qty_mtd, 0) AS omni_sales_qty_mtd, COALESCE(C.SALES_LAST_7_DAYS,0) as sales_qty_l7, CASE WHEN COALESCE(o.new_category, c.new_category) IS NOT NULL THEN COALESCE(o.new_category, c.new_category) WHEN COALESCE(o.sku_group, c.sku_group, s.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN COALESCE(o.sku_group, c.sku_group, s.sku_group) LIKE \'4MSFR%\' THEN \'Perfumes\' ELSE \'Accessories\' END AS new_category, COALESCE(o.designs, c.designs) AS designs, COALESCE(o.collar_new, c.collar_new) AS collar_new, COALESCE(o.sleeve_type, c.sleeve_type) AS sleeve_type, COALESCE(o.fit, c.fit) AS fit, COALESCE(o.style, c.style) AS style, COALESCE(o.material_new, c.material_new) AS material_new, COALESCE(bs.base_stock, 0) AS base_stock, COALESCE(c.fresh_remark, \'Old\') AS fresh_old_remark, COALESCE(c.cut_size, \'NO\') AS cut_size, c.XS_UNITS, c.S_UNITS, c.M_UNITS, c.L_UNITS, c.XL_UNITS, c.XXL_UNITS, c.XL3_UNITS, c.XL4_UNITS, c.XL5_UNITS, c.XL6_UNITS, c.JIT_XS_UNITS, c.JIT_S_UNITS, c.JIT_M_UNITS, c.JIT_L_UNITS, c.JIT_XL_UNITS, c.JIT_2XL_UNITS, c.JIT_3XL_UNITS, c.JIT_4XL_UNITS, c.JIT_5XL_UNITS, c.JIT_6XL_UNITS FROM opening o FULL OUTER JOIN closing c ON o.branch_code = c.branch_code AND o.sku_group = c.sku_group FULL OUTER JOIN sales s ON COALESCE(o.branch_code, c.branch_code) = s.branch_code AND COALESCE(o.sku_group, c.sku_group) = s.sku_group LEFT JOIN sales_mtd smtd ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = smtd.branch_code AND COALESCE(o.sku_group, c.sku_group, s.sku_group) = smtd.sku_group LEFT JOIN omni_sales_30 os30 ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = os30.branch_code AND COALESCE(o.sku_group, c.sku_group, s.sku_group) = os30.sku_group LEFT JOIN omni_sales_mtd osmtd ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = osmtd.branch_code AND COALESCE(o.sku_group, c.sku_group, s.sku_group) = osmtd.sku_group LEFT JOIN base_stock bs ON COALESCE(o.branch_code, c.branch_code, s.branch_code) = bs.branch_code ), filtered AS ( SELECT *, CASE WHEN cut_size = \'NO\' THEN \'Full Size\' ELSE \'Cut Size\' END AS size_category FROM combined WHERE NOT (opening_inventory = 0 AND closing_inventory = 0 AND sales_qty = 0 and jit_qty=0) ), sku_store AS ( SELECT f.*, CASE WHEN (opening_inventory + closing_inventory) > 0 THEN ROUND(sales_qty / ((opening_inventory + closing_inventory) / 2.0), 2) ELSE 0 END AS sell_through_1, SUM(sales_qty) OVER (PARTITION BY cluster, sku_group) AS cluster_sales_qty, SUM(opening_inventory) OVER (PARTITION BY cluster, sku_group) AS cluster_opening_inventory, SUM(closing_inventory) OVER (PARTITION BY cluster, sku_group) AS cluster_closing_inventory, CASE WHEN ( SUM(opening_inventory) OVER (PARTITION BY cluster, sku_group) + SUM(closing_inventory) OVER (PARTITION BY cluster, sku_group) ) > 0 THEN ROUND( SUM(sales_qty) OVER (PARTITION BY cluster, sku_group) / ( ( SUM(opening_inventory) OVER (PARTITION BY cluster, sku_group) + SUM(closing_inventory) OVER (PARTITION BY cluster, sku_group) ) / 2.0 ), 2 ) ELSE 0 END AS cluster_sell_through_1, CASE WHEN ( SUM(opening_inventory) OVER (PARTITION BY branch_code) + SUM(closing_inventory) OVER (PARTITION BY branch_code) ) > 0 THEN ROUND( SUM(sales_qty) OVER (PARTITION BY branch_code) / ( ( SUM(opening_inventory) OVER (PARTITION BY branch_code) + SUM(closing_inventory) OVER (PARTITION BY branch_code) ) / 2.0 ), 2 ) ELSE 0 END AS store_sell_through_1 FROM filtered f ), images AS ( select sku_group,image_url from snitch_db.maplemonk.base_product ), sku_mrp AS ( SELECT CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS sku_group, MAX(mrp) AS mrp FROM snitch_db.maplemonk.unicommerce_live_inventory GROUP BY 1 ), sku_colour AS ( SELECT UPPER(sku_group) AS sku_group, CASE WHEN UPPER(TRIM(color)) IN (\'BLACK\') THEN \'Black\' WHEN UPPER(TRIM(color)) IN (\'ASH GREY\',\'CHARCOAL GREY\',\'DARK GREY\',\'GRAY\',\'GREY\',\'GREYISH BLU\',\'LIGHT GREY\') THEN \'Grey\' WHEN UPPER(TRIM(color)) IN (\'BEIGE\',\'CREAM\',\'IVORY\',\'LIGHT BEIGE\') THEN \'Beige\' WHEN UPPER(TRIM(color)) IN (\'BLUE\',\'BLUE GREY\',\'LIGHT BLUE\',\'SKY BLUE\',\'TEAL\',\'TEAL BLUE\',\'TURQUOISE\') THEN \'Blue\' WHEN UPPER(TRIM(color)) IN (\'DARK BLUE\',\'INDIGO\',\'NAVY\',\'NAVY BLUE\') THEN \'Navy\' WHEN UPPER(TRIM(color)) IN (\'BROWN\',\'DARK BROW\',\'HAZELNUT\',\'LIGHT BROW\',\'TAN\') THEN \'Brown\' WHEN UPPER(TRIM(color)) IN (\'BURGUNDY\',\'MAGENTA\',\'MAROON\') THEN \'Maroon\' WHEN UPPER(TRIM(color)) IN (\'DARK GREE\',\'GREEN\',\'LIGHT GREEN\',\'LIME GREE\',\'MINT\',\'MINT GREEN\',\'SAGE\',\'SAGE GREEN\') THEN \'Green\' WHEN UPPER(TRIM(color)) IN (\'LAVENDER\',\'LILAC\',\'MAUVE\') THEN \'Lavender\' WHEN UPPER(TRIM(color)) IN (\'LIGHT PINK\',\'PEACH\',\'PINK\') THEN \'Pink\' WHEN UPPER(TRIM(color)) IN (\'MULTI\',\'MULTICOLOR\',\'MULTICOLOUR\') THEN \'Multi\' WHEN UPPER(TRIM(color)) IN (\'MUSTARD\',\'YELLOW\') THEN \'Yellow\' WHEN UPPER(TRIM(color)) IN (\'NUDE\',\'WHITE\') THEN \'White\' WHEN UPPER(TRIM(color)) IN (\'OFF WHITE\',\'OFF-WHITE\') THEN \'Off-White\' WHEN UPPER(TRIM(color)) IN (\'OLIVE\',\'OLIVE GREEN\') THEN \'Olive\' WHEN UPPER(TRIM(color)) IN (\'ORANGE\',\'RUST ORANGE\') THEN \'Orange\' WHEN UPPER(TRIM(color)) IN (\'PURPLE\',\'VIOLET\',\'WINE\') THEN \'Purple\' WHEN UPPER(TRIM(color)) IN (\'RED\',\'RUST\') THEN \'Red\' WHEN UPPER(TRIM(color)) IN (\'SILVER\',\'STAINLESS STEEL\') THEN \'Silver\' WHEN UPPER(TRIM(color)) = \'GOLD\' THEN \'Gold\' WHEN UPPER(TRIM(color)) = \'KHAKI\' THEN \'Khaki\' ELSE \'Others\' END AS colour FROM snitch_db.maplemonk.metafields_data ) SELECT ss.cluster AS state, SS.BRANCH_CODE, ss.marketplace_mapped, ss.new_category, ss.sku_group, pj.product_name, img.image_url AS image, ss.fit, CASE WHEN UPPER(ss.sku_group) LIKE \'%4MLX%\' OR UPPER(ss.sku_group) LIKE \'%4LRN%\' OR UPPER(ss.sku_group) LIKE \'%4LPL%\' OR UPPER(ss.sku_group) LIKE \'%4LTR%\' OR UPPER(ss.sku_group) LIKE \'%4LCH%\' OR UPPER(ss.sku_group) LIKE \'%4LJE%\' OR UPPER(ss.sku_group) LIKE \'%4LJK%\' OR UPPER(ss.sku_group) LIKE \'%4LSW%\' OR UPPER(ss.sku_group) LIKE \'%4LHD%\' OR UPPER(ss.sku_group) LIKE \'%4LOS%\' OR UPPER(ss.sku_group) LIKE \'%4LSHS%\' OR UPPER(ss.sku_group) LIKE \'%4LSFS%\' OR UPPER(ss.sku_group) LIKE \'%4LSH%\' OR UPPER(ss.sku_group) LIKE \'%4LBL%\' OR UPPER(ss.sku_group) LIKE \'%4LCA%\' OR UPPER(ss.sku_group) LIKE \'%4LSWT%\' OR UPPER(ss.sku_group) LIKE \'%4LCD%\' OR UPPER(ss.sku_group) LIKE \'%4LJO%\' THEN \'Luxe\' WHEN UPPER(ss.sku_group) LIKE \'%4MBG%\' OR UPPER(ss.sku_group) LIKE \'%4BRN%\' OR UPPER(ss.sku_group) LIKE \'%4BPL%\' OR UPPER(ss.sku_group) LIKE \'%4BTR%\' OR UPPER(ss.sku_group) LIKE \'%4BCH%\' OR UPPER(ss.sku_group) LIKE \'%4BJE%\' OR UPPER(ss.sku_group) LIKE \'%4BJK%\' OR UPPER(ss.sku_group) LIKE \'%4BSW%\' OR UPPER(ss.sku_group) LIKE \'%4BHD%\' OR UPPER(ss.sku_group) LIKE \'%4BOS%\' OR UPPER(ss.sku_group) LIKE \'%4BSHS%\' OR UPPER(ss.sku_group) LIKE \'%4BSFS%\' OR UPPER(ss.sku_group) LIKE \'%4BSH%\' OR UPPER(ss.sku_group) LIKE \'%4BBL%\' OR UPPER(ss.sku_group) LIKE \'%4BCA%\' OR UPPER(ss.sku_group) LIKE \'%4BSWT%\' OR UPPER(ss.sku_group) LIKE \'%4BCD%\' OR UPPER(ss.sku_group) LIKE \'%4BJO%\' THEN \'Plus\' ELSE \'Snitch\' END AS style, CASE WHEN LOWER(ss.STYLE) LIKE \'%linen%\' THEN \'Linen\' WHEN MATERIAL_NEW = \'Cotton\' THEN \'Cotton\' WHEN MATERIAL_NEW IN (\'Tencel\', \'Tencil\', \'Polyester\', \'Terry\', \'Rayon\', \'Nylon\', \'Modal\', \'Others\') THEN \'Polyester\' WHEN MATERIAL_NEW = \'Linen\' THEN \'Linen\' ELSE \'Polyester\' END AS MATERIAL, CASE WHEN TRIM(LOWER(ss.sleeve_type)) IN (\'sleeveless\') THEN \'Sleeveless\' WHEN TRIM(LOWER(ss.sleeve_type)) IN (\'half sleeve\',\'elbow sleeve\') THEN \'Half Sleeve\' WHEN TRIM(LOWER(ss.sleeve_type)) in (\'full sleeve\',\'three-quarter sleeves\') THEN \'Full Sleeve\' ELSE \'Others\' END as sleeve_length, ss.fresh_old_remark, ss.opening_inventory, ss.size_category, ss.base_stock, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) IN (\'GRAPHIC PRINT\',\'PRINTED\',\'GEOMETRIC\',\'FLORAL\',\'TIE & DYE\',\'ANIMAL PRINT\') THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroidered\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' ELSE \'Others\' END WHEN ss.new_category = \'Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(ss.designs)) IN (\'PRINTED\',\'FLORAL\',\'GEOMETRIC\',\'TIE & DYE\',\'GRAPHIC PRINT\',\'ANIMAL PRINT\') THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroidered\' ELSE \'Others\' END ELSE ss.designs END AS designs_mapped, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN TRIM(LOWER(ss.collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(ss.collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(ss.collar_new)) = \'polo\' THEN \'Polo\' ELSE ss.collar_new END ELSE ss.collar_new END AS collar_new_mapped, mrp.mrp, col.colour, ss.sales_qty AS sales_last_30_days, ss.sales_qty_mtd AS sales_mtd, ss.omni_sales_qty AS omni_sales_last_30_days, ss.omni_sales_qty_mtd AS omni_sales_mtd, ss.sales_qty_l7 as sales_last_7_days, ss.closing_inventory AS inventory, ss.jit_qty, ss.num_size_available, ss.XS_UNITS, ss.S_UNITS, ss.M_UNITS, ss.L_UNITS, ss.XL_UNITS, ss.XXL_UNITS, ss.XL3_UNITS, ss.XL4_UNITS, ss.XL5_UNITS, ss.XL6_UNITS, ss.JIT_XS_UNITS, ss.JIT_S_UNITS, ss.JIT_M_UNITS, ss.JIT_L_UNITS, ss.JIT_XL_UNITS, ss.JIT_2XL_UNITS, ss.JIT_3XL_UNITS, ss.JIT_4XL_UNITS, ss.JIT_5XL_UNITS, ss.JIT_6XL_UNITS, ROUND(ss.sell_through_1 * 100, 0) AS str_pct, ROUND(ss.cluster_sell_through_1 * 100, 0) AS cluster_str_pct, CASE WHEN ss.sales_qty = 0 AND ss.closing_inventory > 8 AND ss.num_size_available >= 4 THEN \'0 STR\' WHEN ss.sell_through_1 >= ss.store_sell_through_1 THEN \'Top Selling\' WHEN ss.sell_through_1 < ss.store_sell_through_1 AND ss.size_category = \'Full Size\' AND ss.closing_inventory > 0 THEN \'Low Selling\' ELSE \'Others\' END AS sales_status, case when ss.jit_qty = 0 and ss.closing_inventory > 0 then \'At Store\' when ss.sales_qty = 0 and ss.closing_inventory = 0 and ss.jit_qty > 0 then \'Fresh in Transit\' when ss.sales_qty > 0 and ss.jit_qty > 0 then \'RPL in Transit\' when ss.sales_qty = 0 and ss.closing_inventory > 0 and ss.jit_qty > 0 then \'Stocked+Inbound\' when ss.closing_inventory=0 and ss.jit_qty= 0 then \'Stocked-Out\' else \'Others\' end as in_transit_status, FROM sku_store ss LEFT JOIN snitch_db.maplemonk.product_journey pj ON ss.sku_group = UPPER(pj.sku_group) LEFT JOIN images img ON ss.sku_group = img.sku_group LEFT JOIN sku_mrp mrp ON ss.sku_group = UPPER(mrp.sku_group) LEFT JOIN sku_colour col ON ss.sku_group = col.sku_group WHERE ss.cluster IS NOT NULL and ss.sku_group not like \'PP%\' AND SS.SKU_GROUP NOT LIKE \'NT%\' AND SS.SKU_GROUP NOT LIKE \'GIFT%\' AND SS.SKU_GROUP NOT LIKE \'MP%\' ORDER BY ss.cluster, ss.sales_qty DESC; create or replace table snitch_db.maplemonk.b2b_jour_htmlbase as WITH b2b AS ( SELECT state, final_store, final_status, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN REVERSE(SUBSTR(REVERSE(sku), POSITION(\'-\' IN REVERSE(sku)) + 1)) ELSE sku END AS sku_group, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN REVERSE(SPLIT_PART(REVERSE(sku), \'-\', 1)) ELSE NULL END AS size, qty, order_date, order_name, type, TRY_TO_DATE(NULLIF(TRIM(LOGISTICS_EXPECTED_DELIVERY_DATE), \'\')) AS EDD_original FROM snitch_db.maplemonk.b2b_journey WHERE final_status NOT IN (\'INWARDED\',\'INWARD_PENDING\') AND type NOT IN (\'QCOMM\',\'Qcomm\',\'OTHER\',\'QCOM\') ), meta AS ( SELECT sku_group, product_name, category, designs, collar_new, fit FROM snitch_db.maplemonk.metafields_data WHERE category IS NOT NULL ), pj AS ( SELECT sku_group, image FROM snitch_db.maplemonk.product_journey ), fp AS ( SELECT branch_name_priority, TRY_TO_NUMBER(NULLIF(TRIM(lead_time), \'\')) AS lead_time FROM snitch_db.maplemonk.google_sheet_fresh_priority ) SELECT b2b.state, b2b.final_store, b2b.final_status, b2b.sku_group, b2b.size, b2b.qty, b2b.order_date, b2b.order_name, b2b.type, COALESCE( b2b.EDD_original, DATEADD(\'day\', fp.lead_time, b2b.order_date) ) AS EDD, meta.product_name, meta.category, meta.designs, meta.collar_new, meta.fit, pj.image, fp.lead_time FROM b2b LEFT JOIN meta ON b2b.sku_group = meta.sku_group LEFT JOIN pj ON b2b.sku_group = pj.sku_group LEFT JOIN fp ON b2b.final_store = fp.branch_name_priority; create or replace table snitch_db.maplemonk.offline_git_summary as WITH dist_edd AS ( SELECT order_name, MAX(TO_DATE(delivery_tat)) AS mapped_edd, MAX(TO_DATE(ideal_delivery_date)) AS ideal_edd FROM snitch_db.maplemonk.distribution_analytics GROUP BY 1 ), b2b_base AS ( SELECT bj.state, bj.final_store, bj.final_status, CASE WHEN bj.warehouse_name IN (\'SAPL-NORTH-TAURU\') THEN \'SAPL-NORTH-TAURU\' ELSE \'SOUTH\' END AS warehouse_name, bj.order_date, bj.new_bill_no AS doc_no, bj.courier_partner, bj.tracking_number AS awb_number, bj.tracking_sub_status AS current_status, bj.tracking_latest_message AS current_scan, bj.order_name, bj.type, CASE WHEN UPPER(bj.sku) LIKE \'4C%\' THEN SPLIT_PART(bj.sku, \'-\', 1) || \'-\' || SPLIT_PART(bj.sku, \'-\', 2) || \'-\' || SPLIT_PART(bj.sku, \'-\', 3) WHEN POSITION(\'-\' IN bj.sku) > 0 THEN SPLIT_PART(bj.sku, \'-\', 1) || \'-\' || SPLIT_PART(bj.sku, \'-\', 2) ELSE bj.sku END AS sku_group, bj.qty, de.mapped_edd, de.ideal_edd FROM snitch_db.maplemonk.b2b_journey bj LEFT JOIN dist_edd de ON bj.order_name = de.order_name WHERE bj.final_status NOT IN (\'INWARDED\',\'INWARD_PENDING\') AND bj.type NOT IN (\'QCOMM\',\'Qcomm\',\'OTHER\') AND bj.final_store IS NOT NULL ), b2b AS ( SELECT state, final_store, final_status, warehouse_name, order_date, doc_no, courier_partner, awb_number, current_status, current_scan, LISTAGG(DISTINCT order_name, \',\') WITHIN GROUP (ORDER BY order_name) AS order_names, type, sku_group, SUM(qty) AS qty, MAX(mapped_edd) AS mapped_edd, max(ideal_edd) as ideal_edd FROM b2b_base GROUP BY state, final_store, final_status, warehouse_name, order_date, doc_no, courier_partner, awb_number, current_status, current_scan, type, sku_group ), meta AS ( SELECT DISTINCT sku_group, product_name, category, designs, collar_new, style, fit, material FROM snitch_db.maplemonk.av_master_htmbase WHERE category IS NOT NULL ), pj AS ( SELECT sku_group, image FROM snitch_db.maplemonk.product_journey ), south_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS fresh_order_day, UPPER(TRIM(\"RPL Order Day\")) AS rpl_order_day, UPPER(TRIM(\"Fresh Delivery Day\")) AS fresh_delivery_day, UPPER(TRIM(\"RPL Delivery Day\")) AS rpl_delivery_day, TRY_TO_NUMBER(\"Best TAT\") AS best_tat FROM snitch_db.maplemonk.final_southrulebook ), north_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS fresh_order_day, UPPER(TRIM(\"RPL Order Day\")) AS rpl_order_day, UPPER(TRIM(\"Fresh Delivery Day\")) AS fresh_delivery_day, UPPER(TRIM(\"RPL Delivery Day\")) AS rpl_delivery_day, TRY_TO_NUMBER(\"Best TAT\") AS best_tat FROM snitch_db.maplemonk.north_rule_merch ), base AS ( SELECT b2b.state, b2b.final_store, b2b.order_names, b2b.order_date, b2b.warehouse_name, b2b.sku_group, b2b.qty, b2b.type, b2b.final_status, b2b.courier_partner, b2b.doc_no, b2b.awb_number, b2b.current_status, b2b.current_scan, b2b.mapped_edd, b2b.ideal_edd, meta.product_name, meta.category, meta.designs, meta.collar_new, meta.fit, meta.style, meta.material FROM b2b LEFT JOIN meta ON b2b.sku_group = meta.sku_group LEFT JOIN south_rule sr ON b2b.final_store = sr.store_name LEFT JOIN north_rule nr ON b2b.final_store = nr.store_name ) SELECT state, final_store, order_names, order_date, warehouse_name, sku_group, qty, type, final_status, courier_partner, doc_no, awb_number, current_status, current_scan, COALESCE(mapped_edd, ideal_edd) AS edd, product_name, category, designs, collar_new, fit, style, material FROM base where order_names not like \'QC%\' ORDER BY final_store, order_names, sku_group, type; create or replace table snitch_db.maplemonk.offline_non_replen_cut as WITH wh_inv AS ( SELECT warehouse_location AS zone, UPPER(sku_group) AS sku_group, COALESCE(xs_units, 0) AS wh_xs, COALESCE(s_units, 0) AS wh_s, COALESCE(m_units, 0) AS wh_m, COALESCE(l_units, 0) AS wh_l, COALESCE(xl_units, 0) AS wh_xl, COALESCE(xxl_units, 0) AS wh_xxl, COALESCE(xl3_units, 0) AS wh_3xl, COALESCE(xl4_units, 0) AS wh_4xl, COALESCE(xl5_units, 0) AS wh_5xl, COALESCE(xl6_units, 0) AS wh_6xl FROM snitch_db.maplemonk.availability_master_v2_merged ), store_zone AS ( SELECT DISTINCT branch_code, zone FROM snitch_db.maplemonk.store_category_delta ), store_cut_size AS ( SELECT om.branch_code, sz.zone, om.marketplace_mapped, UPPER(om.sku_group) AS sku_group, om.inventory, om.jit_qty, om.new_category, om.designs, om.collar_new, om.sleeve_type, om.fit, om.style, om.material_new, CASE WHEN COALESCE(om.XS_UNITS,0) + COALESCE(om.JIT_XS_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xs, CASE WHEN COALESCE(om.S_UNITS,0) + COALESCE(om.JIT_S_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_s, CASE WHEN COALESCE(om.M_UNITS,0) + COALESCE(om.JIT_M_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_m, CASE WHEN COALESCE(om.L_UNITS,0) + COALESCE(om.JIT_L_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_l, CASE WHEN COALESCE(om.XL_UNITS,0) + COALESCE(om.JIT_XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xl, CASE WHEN COALESCE(om.XXL_UNITS,0) + COALESCE(om.JIT_2XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xxl, CASE WHEN COALESCE(om.XL3_UNITS,0) + COALESCE(om.JIT_3XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_3xl, CASE WHEN COALESCE(om.XL4_UNITS,0) + COALESCE(om.JIT_4XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_4xl, CASE WHEN COALESCE(om.XL5_UNITS,0) + COALESCE(om.JIT_5XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_5xl, CASE WHEN COALESCE(om.XL6_UNITS,0) + COALESCE(om.JIT_6XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_6xl, COALESCE(om.XS_UNITS,0) + COALESCE(om.JIT_XS_UNITS,0) AS qty_xs, COALESCE(om.S_UNITS,0) + COALESCE(om.JIT_S_UNITS,0) AS qty_s, COALESCE(om.M_UNITS,0) + COALESCE(om.JIT_M_UNITS,0) AS qty_m, COALESCE(om.L_UNITS,0) + COALESCE(om.JIT_L_UNITS,0) AS qty_l, COALESCE(om.XL_UNITS,0) + COALESCE(om.JIT_XL_UNITS,0) AS qty_xl, COALESCE(om.XXL_UNITS,0) + COALESCE(om.JIT_2XL_UNITS,0) AS qty_xxl, COALESCE(om.XL3_UNITS,0) + COALESCE(om.JIT_3XL_UNITS,0) AS qty_3xl, COALESCE(om.XL4_UNITS,0) + COALESCE(om.JIT_4XL_UNITS,0) AS qty_4xl, COALESCE(om.XL5_UNITS,0) + COALESCE(om.JIT_5XL_UNITS,0) AS qty_5xl, COALESCE(om.XL6_UNITS,0) + COALESCE(om.JIT_6XL_UNITS,0) AS qty_6xl FROM snitch_db.maplemonk.offline_master om LEFT JOIN store_zone sz ON om.branch_code = sz.branch_code WHERE om.new_category NOT IN (\'Belts\', \'Bags\', \'Shoes\', \'Sunglasses\', \'Perfumes\') AND om.inventory + om.jit_qty > 0 AND om.base_stock IS NOT NULL ), cut_size_flagged AS ( SELECT s.*, CASE WHEN LEFT(s.SKU_GROUP, 4) IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND (s.s_3xl + s.s_4xl + s.s_5xl + s.s_6xl) < 3 THEN \'YES\' WHEN LEFT(s.SKU_GROUP, 4) NOT IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND ( (s.s_s + s.s_m + s.s_l + s.s_xl) < 3 OR (s.s_xs + s.s_s + s.s_m + s.s_l + s.s_xl + s.s_xxl) < 4 ) THEN \'YES\' ELSE \'NO\' END AS cut_size_at_store FROM store_cut_size s ), cut_size_only AS ( SELECT * FROM cut_size_flagged where cut_size_at_store in (\'YES\') ), with_replenishment AS ( SELECT c.*, CASE WHEN c.qty_xs + COALESCE(w.wh_xs,0) > 2 THEN 1 ELSE 0 END AS r_xs, CASE WHEN c.qty_s + COALESCE(w.wh_s,0) > 3 THEN 1 ELSE 0 END AS r_s, CASE WHEN c.qty_m + COALESCE(w.wh_m,0) > 5 THEN 1 ELSE 0 END AS r_m, CASE WHEN c.qty_l + COALESCE(w.wh_l,0) > 5 THEN 1 ELSE 0 END AS r_l, CASE WHEN c.qty_xl + COALESCE(w.wh_xl,0) > 3 THEN 1 ELSE 0 END AS r_xl, CASE WHEN c.qty_xxl + COALESCE(w.wh_xxl,0) > 2 THEN 1 ELSE 0 END AS r_xxl, CASE WHEN c.qty_3xl + COALESCE(w.wh_3xl,0) > 3 THEN 1 ELSE 0 END AS r_3xl, CASE WHEN c.qty_4xl + COALESCE(w.wh_4xl,0) > 3 THEN 1 ELSE 0 END AS r_4xl, CASE WHEN c.qty_5xl + COALESCE(w.wh_5xl,0) > 3 THEN 1 ELSE 0 END AS r_5xl, CASE WHEN c.qty_6xl + COALESCE(w.wh_6xl,0) > 3 THEN 1 ELSE 0 END AS r_6xl FROM cut_size_only c LEFT JOIN wh_inv w ON w.zone = c.zone AND w.sku_group = c.sku_group ), final AS ( SELECT r.*, CASE WHEN LEFT(r.SKU_GROUP, 4) IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND (r.r_3xl + r.r_4xl + r.r_5xl + r.r_6xl) < 3 THEN \'YES\' WHEN LEFT(r.SKU_GROUP, 4) NOT IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND ( (r.r_s + r.r_m + r.r_l + r.r_xl) < 3 OR (r.r_xs + r.r_s + r.r_m + r.r_l + r.r_xl + r.r_xxl) < 4 ) THEN \'YES\' ELSE \'NO\' END AS cut_size_after_replenishment FROM with_replenishment r ) SELECT branch_code, zone, marketplace_mapped, sku_group, inventory, jit_qty, new_category, designs, collar_new, sleeve_type, fit, style, material_new, cut_size_at_store, cut_size_after_replenishment FROM final WHERE cut_size_after_replenishment = \'YES\' ; create or replace table snitch_db.maplemonk.fifo_ageing_v1 as WITH po_data AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(PO_DATE::STRING), \'\'), \'DD-MM-YYYY\') AS po_date, CASE WHEN UPPER(sku::STRING) LIKE \'4C-%\' THEN SPLIT_PART(sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 2) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 3) WHEN UPPER(sku::STRING) LIKE \'MP-%\' THEN SPLIT_PART(sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 2) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 3) WHEN POSITION(\'-\' IN sku::STRING) > 0 THEN SPLIT_PART(sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(sku::STRING, \'-\', 2) ELSE sku::STRING END AS sku_group, UPPER(TRIM(sku::STRING)) AS sku, SUM(TRY_TO_NUMBER(NULLIF(TRIM(PO_QTY::STRING), \'\'))) AS po_qty, MAX(TRY_TO_NUMBER(NULLIF(TRIM(rate::STRING), \'\'), 38, 2)) AS rate FROM SNITCH_DB.MAPLEMONK.S3_UC_PO WHERE TRY_TO_DATE(NULLIF(TRIM(PO_DATE::STRING), \'\'), \'DD-MM-YYYY\') IS NOT NULL GROUP BY 1, 2, 3 ), po_ranked AS ( SELECT sku, sku_group, po_date, po_qty, rate, SUM(po_qty) OVER (PARTITION BY sku ORDER BY po_date DESC ROWS UNBOUNDED PRECEDING) AS cumulative_qty FROM po_data ), wh_inv AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS sku, SUM(COALESCE(inventory, 0)) + SUM(COALESCE(\"Inventory Not Synced\", 0)) + SUM(COALESCE(\"Inventory Blocked\", 0)) + SUM(COALESCE(\"Bad Inventory\", 0)) + SUM(COALESCE(\"Putback Pending\", 0)) + SUM(COALESCE(\"Putaway Pending\", 0)) + SUM(COALESCE(\"Pending Inventory Assessment\", 0)) AS wh_qty FROM snitch_db.maplemonk.unicommerce_live_inventory GROUP BY 1 ), offline_inv AS ( SELECT UPPER(TRIM(addlitemcode)) AS sku, SUM(TRY_TO_NUMBER(NULLIF(TRIM(stock_qty::STRING), \'\'))) AS offline_qty FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand GROUP BY 1 ), offline_jit AS ( SELECT UPPER(TRIM(\"ITEM CODE\")) AS sku, SUM(TRY_TO_NUMBER(NULLIF(TRIM(qty::STRING), \'\'))) AS jit_qty FROM snitch_db.maplemonk.jit_offline_goods GROUP BY 1 ), cost_lookup AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS sku, MAX(TRY_TO_NUMBER(NULLIF(TRIM(\"Cost Price\"::STRING), \'\'), 38, 2)) AS cost_price FROM snitch_db.maplemonk.unicommerce_live_inventory GROUP BY 1 ), cost_lookup_group AS ( SELECT CASE WHEN UPPER(sku) LIKE \'4C-%\' THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) || \'-\' || SPLIT_PART(sku, \'-\', 3) WHEN UPPER(sku) LIKE \'MP-%\' THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) || \'-\' || SPLIT_PART(sku, \'-\', 3) WHEN POSITION(\'-\' IN sku) > 0 THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) ELSE sku END AS sku_group, AVG(cost_price) AS cost_price FROM cost_lookup WHERE cost_price IS NOT NULL GROUP BY 1 ), inventory AS ( SELECT COALESCE(w.sku, o.sku, j.sku) AS sku, COALESCE(w.wh_qty, 0) AS wh_qty, COALESCE(o.offline_qty, 0) AS offline_qty, COALESCE(j.jit_qty, 0) AS jit_qty, COALESCE(w.wh_qty, 0) + COALESCE(o.offline_qty, 0) + COALESCE(j.jit_qty, 0) AS total_inventory FROM wh_inv w FULL OUTER JOIN offline_inv o ON w.sku = o.sku FULL OUTER JOIN offline_jit j ON COALESCE(w.sku, o.sku) = j.sku WHERE COALESCE(w.wh_qty, 0) + COALESCE(o.offline_qty, 0) + COALESCE(j.jit_qty, 0) > 0 ), allocated AS ( SELECT p.sku, p.sku_group, p.po_date, p.rate, COALESCE(p.rate, c.cost_price) AS cost_price, GREATEST(0, LEAST(p.po_qty, i.total_inventory - (p.cumulative_qty - p.po_qty)) ) AS allocated_qty, CASE WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 90 THEN \'0-90\' WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 180 THEN \'90-180\' WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 270 THEN \'180-270\' WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 360 THEN \'270-360\' ELSE \'360+\' END AS ageing_bucket FROM po_ranked p INNER JOIN inventory i ON p.sku = i.sku LEFT JOIN cost_lookup c ON p.sku = c.sku ), missing_inv AS ( SELECT i.sku, CASE WHEN UPPER(i.sku) LIKE \'4C-%\' THEN SPLIT_PART(i.sku, \'-\', 1) || \'-\' || SPLIT_PART(i.sku, \'-\', 2) || \'-\' || SPLIT_PART(i.sku, \'-\', 3) WHEN UPPER(i.sku) LIKE \'MP-%\' THEN SPLIT_PART(i.sku, \'-\', 1) || \'-\' || SPLIT_PART(i.sku, \'-\', 2) || \'-\' || SPLIT_PART(i.sku, \'-\', 3) WHEN POSITION(\'-\' IN i.sku) > 0 THEN SPLIT_PART(i.sku, \'-\', 1) || \'-\' || SPLIT_PART(i.sku, \'-\', 2) ELSE i.sku END AS sku_group, i.total_inventory FROM inventory i LEFT JOIN (SELECT DISTINCT sku FROM po_data) p ON i.sku = p.sku WHERE p.sku IS NULL ), missing_inv_group AS ( SELECT sku_group, SUM(total_inventory) AS total_inventory FROM missing_inv GROUP BY 1 ), putaway_data AS ( SELECT TRY_TO_DATE(pt.putaway_completed_date::STRING, \'DD-MM-YYYY\') AS po_date, pt.skugroup AS sku_group, SUM(TRY_TO_NUMBER(NULLIF(TRIM(pt.PUTAWAY_COMPLETED_QUANTITY::STRING), \'\'))) AS po_qty FROM snitch_db.maplemonk.putaway_tracking pt INNER JOIN missing_inv_group m ON pt.skugroup = m.sku_group WHERE pt.final_type = \'New Inward\' AND pt.skugroup IS NOT NULL AND TRY_TO_DATE(pt.putaway_completed_date::STRING, \'DD-MM-YYYY\') IS NOT NULL GROUP BY 1, 2 ), putaway_ranked AS ( SELECT sku_group, po_date, po_qty, SUM(po_qty) OVER (PARTITION BY sku_group ORDER BY po_date DESC ROWS UNBOUNDED PRECEDING) AS cumulative_qty FROM putaway_data ), putaway_allocated AS ( SELECT NULL::STRING AS sku, p.sku_group, p.po_date, NULL::NUMBER(38,2) AS rate, c.cost_price, GREATEST(0, LEAST(p.po_qty, m.total_inventory - (p.cumulative_qty - p.po_qty)) ) AS allocated_qty, CASE WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 90 THEN \'0-90\' WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 180 THEN \'90-180\' WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 270 THEN \'180-270\' WHEN DATEDIFF(\'day\', p.po_date, CURRENT_DATE()) <= 360 THEN \'270-360\' ELSE \'360+\' END AS ageing_bucket FROM putaway_ranked p INNER JOIN missing_inv_group m ON p.sku_group = m.sku_group LEFT JOIN cost_lookup_group c ON p.sku_group = c.sku_group ), combined AS ( SELECT sku, sku_group, po_date, rate, cost_price, allocated_qty, ageing_bucket FROM allocated UNION ALL SELECT sku, sku_group, po_date, rate, cost_price, allocated_qty, ageing_bucket FROM putaway_allocated ) SELECT sku_group, SUM(allocated_qty) AS total_qty, SUM(allocated_qty * rate) AS total_value, SUM(allocated_qty * cost_price) AS total_cogs, SUM(CASE WHEN ageing_bucket = \'0-90\' THEN allocated_qty * cost_price ELSE 0 END) AS cogs_0_90, SUM(CASE WHEN ageing_bucket = \'90-180\' THEN allocated_qty * cost_price ELSE 0 END) AS cogs_90_180, SUM(CASE WHEN ageing_bucket = \'180-270\' THEN allocated_qty * cost_price ELSE 0 END) AS cogs_180_270, SUM(CASE WHEN ageing_bucket = \'270-360\' THEN allocated_qty * cost_price ELSE 0 END) AS cogs_270_360, SUM(CASE WHEN ageing_bucket = \'360+\' THEN allocated_qty * cost_price ELSE 0 END) AS cogs_360_plus, MAX(DATEDIFF(\'day\', po_date, CURRENT_DATE())) AS max_ageing_days, DIV0( SUM(allocated_qty * cost_price * DATEDIFF(\'day\', po_date, CURRENT_DATE())), SUM(allocated_qty * cost_price) ) AS weighted_ageing_days, CASE WHEN DIV0( SUM(allocated_qty * cost_price * DATEDIFF(\'day\', po_date, CURRENT_DATE())), SUM(allocated_qty * cost_price) ) <= 90 THEN \'0-90\' WHEN DIV0( SUM(allocated_qty * cost_price * DATEDIFF(\'day\', po_date, CURRENT_DATE())), SUM(allocated_qty * cost_price) ) <= 180 THEN \'90-180\' WHEN DIV0( SUM(allocated_qty * cost_price * DATEDIFF(\'day\', po_date, CURRENT_DATE())), SUM(allocated_qty * cost_price) ) <= 270 THEN \'180-270\' WHEN DIV0( SUM(allocated_qty * cost_price * DATEDIFF(\'day\', po_date, CURRENT_DATE())), SUM(allocated_qty * cost_price) ) <= 360 THEN \'270-360\' ELSE \'360+\' END AS ageing_bucket FROM combined WHERE allocated_qty > 0 GROUP BY sku_group ORDER BY weighted_ageing_days DESC; = create or replace table snitch_db.maplemonk.ecosystem_cut_1 as WITH product_images AS ( SELECT sku_group, image_url FROM snitch_db.maplemonk.base_product ), metafields_std AS ( SELECT sku_group, product_name, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' ELSE \'Others\' END WHEN UPPER(category) LIKE \'%SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' T